from copy import deepcopy


def run_pipeline(items, stages):
    if not isinstance(items, (list, tuple)):
        raise TypeError("items must be a list or tuple")
    if not isinstance(stages, (list, tuple)):
        raise TypeError("stages must be a list or tuple")
    if any(not isinstance(item, dict) for item in items):
        raise TypeError("items must contain dictionaries")
    if any(not callable(stage) for stage in stages):
        raise TypeError("stages must contain callables")

    results = []
    for item in items:
        current = dict(item)
        for stage in stages:
            current = stage(current)
            if not isinstance(current, dict):
                raise TypeError("stages must return dictionaries")
            current = deepcopy(current)
        results.append(deepcopy(current))
    return results
```

